function requestBody(): array { $data = json_decode(file_get_contents('php://input') ?: '{}', true); return is_array($data) ? array_map(fn($value) => is_string($value) ? trim(strip_tags($value)) : $value, $data) : []; }
function requireAdmin(): int { session_name('srinidhi_admin'); session_start(['cookie_httponly'=>true,'cookie_secure'=>env('SESSION_SECURE','false') === 'true','cookie_samesite'=>'Strict']); if (empty($_SESSION['admin_id'])) Response::error('Authentication required.', 401); return (int)$_SESSION['admin_id']; }
function makeSlug(string $value): string { return trim(preg_replace('/[^a-z0-9]+/i', '-', strtolower($value)), '-'); }
function record(string $table, int $id): array { $stmt = db()->prepare("SELECT * FROM `$table` WHERE id=:id"); $stmt->execute(['id'=>$id]); $row = $stmt->fetch(); if (!$row) Response::error('Record not found.', 404); return $row; }
function projectData(array $data): array { requireFields($data, ['title','category','status','location','area_sqft','description','cover_image']); $errors=[]; if (mb_strlen($data['title'])<3 || mb_strlen($data['title'])>120) $errors['title']='Title must be 3-120 characters.'; if (!in_array($data['category'],['residential','commercial','industrial'],true)) $errors['category']='Invalid category.'; if (!in_array($data['status'],['completed','ongoing','upcoming'],true)) $errors['status']='Invalid status.'; if (filter_var($data['area_sqft'],FILTER_VALIDATE_INT)===false || (int)$data['area_sqft']<1) $errors['area_sqft']='Area must be positive.'; if (mb_strlen($data['description'])>2000) $errors['description']='Description is too long.'; if ($errors) Response::error('Please correct the highlighted fields.',422,$errors); return $data; }
function serviceData(array $data): array { requireFields($data,['title','short_description','description']); if (mb_strlen($data['title'])<3 || mb_strlen($data['title'])>120) Response::error('Service title must be 3-120 characters.',422); return $data; }
$parts=explode('/',trim(parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH),'/')); $resource=$parts[1]??''; $action=$parts[2]??null; $method=$_SERVER['REQUEST_METHOD'];
try {
 if ($resource==='services' && $method==='GET' && !$action) { Response::ok(db()->query('SELECT * FROM services WHERE is_active=1 ORDER BY display_order,id')->fetchAll(),'Services loaded.'); }
 elseif ($resource==='projects' && $method==='GET' && !$action) { $where=['1=1'];$params=[];foreach(['category','status'] as $filter) if(!empty($_GET[$filter])){$where[]="$filter=:$filter";$params[$filter]=$_GET[$filter];}$stmt=db()->prepare('SELECT * FROM projects WHERE '.implode(' AND ',$where).' ORDER BY is_featured DESC,created_at DESC');$stmt->execute($params);$items=$stmt->fetchAll();Response::ok(['items'=>$items,'pagination'=>['page'=>1,'pages'=>1,'total'=>count($items)]],'Projects loaded.'); }
 elseif ($resource==='projects' && $method==='GET' && $action && !ctype_digit($action)) { $stmt=db()->prepare('SELECT p.*,GROUP_CONCAT(pi.image_path ORDER BY pi.display_order) AS gallery FROM projects p LEFT JOIN project_images pi ON pi.project_id=p.id WHERE p.slug=:slug GROUP BY p.id');$stmt->execute(['slug'=>$action]);$item=$stmt->fetch();if(!$item)Response::error('Project not found.',404);$item['images']=$item['gallery']?explode(',',$item['gallery']):[$item['cover_image']];unset($item['gallery']);Response::ok($item,'Project loaded.'); }
 elseif ($resource==='enquiries' && $method==='POST') { $data=validEnquiry(requestBody());$stmt=db()->prepare('INSERT INTO enquiries (name,email,phone,subject,message,project_id) VALUES (:name,:email,:phone,:subject,:message,:project_id)');$stmt->execute(['name'=>$data['name'],'email'=>$data['email'],'phone'=>$data['phone'],'subject'=>$data['subject'],'message'=>$data['message'],'project_id'=>$data['project_id']??null]);Response::json(true,['id'=>db()->lastInsertId()],'Enquiry received.',201); }
 elseif ($resource==='uploads' && $method==='POST') { requireAdmin();$filename=validImageUpload($_FILES['image']??null);$dest=__DIR__.'/uploads/'.$filename;if(!move_uploaded_file($_FILES['image']['tmp_name'],$dest))Response::error('Could not save the uploaded image.',500);Response::json(true,['path'=>'/uploads/'.$filename],'Image uploaded.',201); }
 elseif ($resource==='auth' && $action==='login' && $method==='POST') { session_name('srinidhi_admin');session_start(['cookie_httponly'=>true,'cookie_secure'=>env('SESSION_SECURE','false')==='true','cookie_samesite'=>'Strict']);$data=requestBody();requireFields($data,['email','password']);$stmt=db()->prepare('SELECT id,name,email,password_hash FROM admins WHERE email=:email LIMIT 1');$stmt->execute(['email'=>strtolower($data['email'])]);$admin=$stmt->fetch();if(!$admin || !password_verify($data['password'],$admin['password_hash']))Response::error('Unable to sign in with those details.',401);session_regenerate_id(true);$_SESSION['admin_id']=$admin['id'];db()->prepare('UPDATE admins SET last_login=NOW() WHERE id=:id')->execute(['id'=>$admin['id']]);Response::ok(['admin'=>['id'=>$admin['id'],'name'=>$admin['name'],'email'=>$admin['email']]],'Signed in.'); }
