 elseif (in_array($resource,['projects','services'],true) && $method==='GET' && $action && ctype_digit($action)) { requireAdmin();Response::ok(record($resource,(int)$action),'Record loaded.'); }
 elseif (in_array($resource,['projects','services'],true) && $method==='POST') { requireAdmin();$data=requestBody();if($resource==='projects'){$data=projectData($data);$stmt=db()->prepare('INSERT INTO projects (title,slug,category,status,location,area_sqft,start_date,end_date,description,cover_image,is_featured) VALUES (:title,:slug,:category,:status,:location,:area_sqft,:start_date,:end_date,:description,:cover_image,:is_featured)');$stmt->execute(['title'=>$data['title'],'slug'=>makeSlug($data['title']),'category'=>$data['category'],'status'=>$data['status'],'location'=>$data['location'],'area_sqft'=>$data['area_sqft'],'start_date'=>$data['start_date']??null,'end_date'=>$data['end_date']??null,'description'=>$data['description'],'cover_image'=>$data['cover_image'],'is_featured'=>(int)($data['is_featured']??0)]);}else{$data=serviceData($data);$stmt=db()->prepare('INSERT INTO services (title,slug,short_description,description,icon_or_image,display_order) VALUES (:title,:slug,:short_description,:description,:icon_or_image,:display_order)');$stmt->execute(['title'=>$data['title'],'slug'=>makeSlug($data['title']),'short_description'=>$data['short_description'],'description'=>$data['description'],'icon_or_image'=>$data['icon_or_image']??'hard-hat','display_order'=>(int)($data['display_order']??0)]);}Response::json(true,record($resource,(int)db()->lastInsertId()),'Created.',201); }
