 elseif (in_array($resource,['projects','services'],true) && $method==='DELETE' && $action && ctype_digit($action)) { requireAdmin();record($resource,(int)$action);db()->prepare("DELETE FROM `$resource` WHERE id=:id")->execute(['id'=>(int)$action]);Response::ok(null,'Deleted.'); }
 elseif ($resource==='enquiries' && $method==='GET') { requireAdmin();Response::ok(db()->query('SELECT e.*,p.title AS project_title FROM enquiries e LEFT JOIN projects p ON p.id=e.project_id ORDER BY e.created_at DESC')->fetchAll(),'Enquiries loaded.'); }
 elseif ($resource==='enquiries' && $method==='PATCH' && $action && ctype_digit($action)) { requireAdmin();$data=requestBody();if(!in_array($data['status']??'', ['new','in_progress','completed'],true))Response::error('Invalid enquiry status.',422);record('enquiries',(int)$action);db()->prepare('UPDATE enquiries SET status=:status WHERE id=:id')->execute(['status'=>$data['status'],'id'=>(int)$action]);Response::ok(record('enquiries',(int)$action),'Status updated.'); }
 elseif ($resource==='enquiries' && $method==='DELETE' && $action && ctype_digit($action)) { requireAdmin();record('enquiries',(int)$action);db()->prepare('DELETE FROM enquiries WHERE id=:id')->execute(['id'=>(int)$action]);Response::ok(null,'Deleted.'); }
 elseif ($resource==='health' && $method==='GET') { $checks=['env_file'=>is_file(dirname(__DIR__).'/.env'),'db_connect'=>false,'tables'=>[]]; try { $pdo=db(); $checks['db_connect']=true; foreach(['admins','services','projects','project_images','enquiries'] as $t){ try { $pdo->query("SELECT 1 FROM `$t` LIMIT 1"); $checks['tables'][$t]=true; } catch (\Throwable $te) { $checks['tables'][$t]=false; } } $checks['admin_seeded']=(int)$pdo->query('SELECT COUNT(*) FROM admins')->fetchColumn()>0; } catch (\Throwable $ce) { $checks['db_error']=$ce->getMessage(); } Response::ok($checks,'Health check complete.'); }
 else Response::error('Endpoint not found.',404);
} catch (PDOException $e) {
    $raw = $e->getMessage();
    $sqlState = $e->errorInfo[0] ?? (string) $e->getCode();
    error_log('API database error ['.$sqlState.']: '.$raw);
    if (str_starts_with($raw, 'connection:')) {
        // Thrown from db(): the connection itself never opened.
        Response::error('Could not connect to the database. Check that MySQL is running, that backend/.env has the correct DB_HOST/DB_NAME/DB_USER/DB_PASSWORD, and that the database from database/schema.sql exists.', 500);
    }
    if ((int) ($e->errorInfo[1] ?? 0) === 1062) Response::error('A record with that title or slug already exists.', 409);
    if ((int) ($e->errorInfo[1] ?? 0) === 1146) Response::error('A required database table is missing. Re-run database/schema.sql against the database in backend/.env.', 500);
    if ((int) ($e->errorInfo[1] ?? 0) === 1452) Response::error('That reference does not exist (invalid related record).', 422);
    Response::error('A database error occurred: ' . $raw, 500);
